/* CSS PART 1 OF 2 */

:root {
  --color-primary: #315c52;
  --color-accent: #e6b879;
  --color-background: #f7f5ef;
  --color-text: #29352f;
  --font-body: Arial, sans-serif;
  --content-width: 1100px;
}

body {
  margin: 0;
  font-family: var(--font-body);
  color: var(--color-text);
  background: var(--color-background);
  line-height: 1.6;
}

.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 6%;
  background: #ffffff;
}

.hero {
  padding: 96px 6%;
  text-align: center;
  background: var(--color-primary);
  color: #ffffff;
}
